@namespace sv_3735063104a248d7b2976e8b3bf9437d.Components.Application

<div class="step-content">
    <h2>Review & Submit</h2>
    <p class="step-description">Please review your application before submitting.</p>

    <div class="review-section">
        <div class="review-section-header">
            <h3>Personal Information</h3>
            <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(0)">Edit</button>
        </div>
        <dl class="review-data">
            <dt>Name</dt><dd>@FullName</dd>
            <dt>Email</dt><dd>@Email</dd>
            <dt>Phone</dt><dd>@Phone</dd>
            <dt>Address</dt><dd>@Address</dd>
        </dl>
    </div>

    <div class="review-section">
        <div class="review-section-header">
            <h3>Work History</h3>
            <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
        </div>
        @foreach (var entry in WorkEntries)
        {
            <div class="review-work-entry">
                <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
                <div class="review-dates">
                    @entry.StartDate.ToString("MMM yyyy") – @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")
                </div>
                @if (!string.IsNullOrWhiteSpace(entry.Description))
                {
                    <p class="review-description">@entry.Description</p>
                }
            </div>
        }
    </div>

    <div class="review-section">
        <div class="review-section-header">
            <h3>References</h3>
            <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
        </div>
        @foreach (var r in References)
        {
            <div class="review-reference">
                <strong>@r.Name</strong> — @r.Relationship
                <div>@r.Email @(!string.IsNullOrWhiteSpace(r.Phone) ? $"| {r.Phone}" : "")</div>
            </div>
        }
    </div>

    <div class="review-section">
        <div class="review-section-header">
            <h3>Cover Letter</h3>
            <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
        </div>
        <p class="review-cover-letter">@CoverLetter</p>
    </div>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-message">@ErrorMessage</div>
    }

    <div class="step-actions">
        <button class="btn btn-outline" @onclick="OnBack">Back</button>
        <button class="btn btn-primary btn-submit" @onclick="HandleSubmit" disabled="@IsSubmitting">
            @if (IsSubmitting)
            {
                <span>Submitting...</span>
            }
            else
            {
                <span>Submit Application</span>
            }
        </button>
    </div>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter] public List<WorkHistoryStep.WorkEntryModel> WorkEntries { get; set; } = new();
    [Parameter] public List<ReferencesStep.ReferenceModel> References { get; set; } = new();
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<int> OnEditStep { get; set; }
    [Parameter] public EventCallback OnSubmit { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public bool IsSubmitting { get; set; }
    [Parameter] public string? ErrorMessage { get; set; }

    private async Task HandleSubmit()
    {
        await OnSubmit.InvokeAsync();
    }
}

arguments.file_text:
@page "/apply"
@using sv_3735063104a248d7b2976e8b3bf9437d.Components.Application
@using sv_3735063104a248d7b2976e8b3bf9437d.Services
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-container">
    @if (SubmittedApplicationId.HasValue)
    {
        <div class="confirmation">
            <div class="confirmation-icon">&#10003;</div>
            <h2>Application Submitted!</h2>
            <p>Thank you for applying. Your application ID is:</p>
            <div class="application-id">#@SubmittedApplicationId</div>
            <p>We will review your application and get back to you soon.</p>
        </div>
    }
    else
    {
        <StepIndicator CurrentStep="@CurrentStep" StepNames="@StepNames" OnStepClicked="GoToStep" />

        @switch (CurrentStep)
        {
            case 0:
                <PersonalInfoStep
                    FullName="@PersonalFullName"
                    Email="@PersonalEmail"
                    Phone="@PersonalPhone"
                    Address="@PersonalAddress"
                    OnNext="HandlePersonalInfoNext" />
                break;

            case 1:
                <WorkHistoryStep
                    Entries="@WorkEntries"
                    OnNext="HandleWorkHistoryNext"
                    OnBack="GoBack" />
                break;

            case 2:
                <ReferencesStep
                    References="@ReferenceEntries"
                    OnNext="HandleReferencesNext"
                    OnBack="GoBack" />
                break;

            case 3:
                <CoverLetterStep
                    CoverLetter="@CoverLetterText"
                    OnNext="HandleCoverLetterNext"
                    OnBack="GoBack" />
                break;

            case 4:
                <ReviewStep
                    FullName="@PersonalFullName"
                    Email="@PersonalEmail"
                    Phone="@PersonalPhone"
                    Address="@PersonalAddress"
                    WorkEntries="@WorkEntries"
                    References="@ReferenceEntries"
                    CoverLetter="@CoverLetterText"
                    IsSubmitting="@IsSubmitting"
                    ErrorMessage="@SubmitError"
                    OnEditStep="GoToStep"
                    OnSubmit="HandleSubmit"
                    OnBack="GoBack" />
                break;
        }
    }
</div>

@code {
    private static readonly List<string> StepNames = new()
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    private int CurrentStep;
    private int? SubmittedApplicationId;
    private bool IsSubmitting;
    private string? SubmitError;

    // Step 1 state
    private string PersonalFullName = "";
    private string PersonalEmail = "";
    private string PersonalPhone = "";
    private string PersonalAddress = "";

    // Step 2 state
    private List<WorkHistoryStep.WorkEntryModel> WorkEntries = new();

    // Step 3 state
    private List<ReferencesStep.ReferenceModel> ReferenceEntries = new();

    // Step 4 state
    private string CoverLetterText = "";

    private async Task HandlePersonalInfoNext(PersonalInfoStep.PersonalInfoResult result)
    {
        // Validate email via service
        var isValid = await ApplicationService.ValidateEmailAsync(result.Email);
        if (!isValid)
        {
            // Re-render will show error via the child's ErrorMessage — but we need to communicate back.
            // Instead, we keep old values and don't advance.
            // For simplicity, we set and let the page show an alert-style message.
            return;
        }

        PersonalFullName = result.FullName;
        PersonalEmail = result.Email;
        PersonalPhone = result.Phone;
        PersonalAddress = result.Address;
        CurrentStep = 1;
    }

