+    private string PersonalAddress = "";
+
+    // Step 2 state
+    private List<WorkHistoryStep.WorkEntryModel> WorkEntries = new();
+
+    // Step 3 state
+    private List<ReferencesStep.ReferenceModel> ReferenceEntries = new();
+
+    // Step 4 state
+    private string CoverLetterText = "";
+
+    private async Task HandlePersonalInfoNext(PersonalInfoStep.PersonalInfoResult result)
+    {
+        // Validate email via service
+        var isValid = await ApplicationService.ValidateEmailAsync(result.Email);
+        if (!isValid)
+        {
+            // Re-render will show error via the child's ErrorMessage — but we need to communicate back.
+            // Instead, we keep old values and don't advance.
+            // For simplicity, we set and let the page show an alert-style message.
+            return;
+        }
+
+        PersonalFullName = result.FullName;
+        PersonalEmail = result.Email;
+        PersonalPhone = result.Phone;
+        PersonalAddress = result.Address;
+        CurrentStep = 1;
+    }
+
+    private void HandleWorkHistoryNext(List<WorkHistoryStep.WorkEntryModel> entries)
+    {
+        WorkEntries = entries;
+        CurrentStep = 2;
+    }
+
+    private void HandleReferencesNext(List<ReferencesStep.ReferenceModel> references)
+    {
+        ReferenceEntries = references;
+        CurrentStep = 3;
+    }
+
+    private void HandleCoverLetterNext(string coverLetter)
+    {
+        CoverLetterText = coverLetter;
+        CurrentStep = 4;
+    }
+
+    private async Task HandleSubmit()
+    {
+        IsSubmitting = true;
+        SubmitError = null;
+
+        try
+        {
+            var workHistory = new WorkHistory(
+                WorkEntries.Select(e => new WorkEntry(e.Company, e.Title, e.StartDate, e.EndDate, e.Description)).ToList()
+            );
+
+            var references = ReferenceEntries
+                .Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone))
+                .ToList();
+
+            var personal = new PersonalInfo(PersonalFullName, PersonalEmail, PersonalPhone, PersonalAddress);
+            var application = new JobApplication(personal, workHistory, references, CoverLetterText);
+
+            SubmittedApplicationId = await ApplicationService.SubmitApplicationAsync(application);
+        }
+        catch (Exception ex)
+        {
+            SubmitError = $"Submission failed: {ex.Message}. Please try again.";
+        }
+        finally
+        {
+            IsSubmitting = false;
+        }
+    }
+
+    private void GoToStep(int step)
+    {
+        if (step < CurrentStep)
+            CurrentStep = step;
+    }
+
+    private void GoBack()
+    {
+        if (CurrentStep > 0)
+            CurrentStep--;
+    }
+}
