    private void HandleCompanyInput(ChangeEventArgs e)
    {
        Company = e.Value?.ToString() ?? string.Empty;
        NotifyChanged();
    }

    private void HandleTitleInput(ChangeEventArgs e)
    {
        Title = e.Value?.ToString() ?? string.Empty;
        NotifyChanged();
    }

    private void HandleStartDateChange(ChangeEventArgs e)
    {
        if (DateTime.TryParse(e.Value?.ToString(), out var date))
            StartDate = date;
        NotifyChanged();
    }

    private void HandleEndDateChange(ChangeEventArgs e)
    {
        var val = e.Value?.ToString();
        EndDate = string.IsNullOrEmpty(val) ? null : DateTime.TryParse(val, out var d) ? d : null;
        NotifyChanged();
    }

    private void HandleCurrentChange(ChangeEventArgs e)
    {
        IsCurrent = (bool)(e.Value ?? false);
        if (IsCurrent) EndDate = null;
        NotifyChanged();
    }

    private void HandleDescriptionInput(ChangeEventArgs e)
    {
        Description = e.Value?.ToString() ?? string.Empty;
        NotifyChanged();
    }

    private void NotifyChanged()
    {
        OnChanged.InvokeAsync(new WorkEntryData(Company, Title, StartDate, IsCurrent ? null : EndDate, IsCurrent, Description));
    }

    public record WorkEntryData(string Company, string Title, DateTime StartDate, DateTime? EndDate, bool IsCurrent, string Description);
}

